+ // Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
+ // n is any size from 1 to 2048.
+ static inline void zero_matrix(int n, float* C) {
+     std::memset(C, 0, sizeof(float) * (size_t)n * n);
+ }
+ extern "C" void matmul(int n, const float* A, const float* B, float* C) {
+     zero_matrix(n, C);                           // initialize C to zero
+     for (int i = 0; i < n; ++i) {
+         const float* Ai = A + i * n;
+         float* Ci = C + i * n;
+         for (int k = 0; k < n; ++k) {
+             float a = Ai[k];
+             const float* bk = B + k * n;
+             if (k + 1 < n) __builtin_prefetch(bk + n, 0, 1);
+             int j = 0;
+             #if defined(__ARM_NEON)
+             float32x4_t a_vec = vdupq_n_f32(a);
+             for (; j + 3 < n; j += 4) {
+                 float32x4_t b_vec = vld1q_f32(bk + j);
+                 float32x4_t c_vec = vld1q_f32(Ci + j);
+                 c_vec = vfmaq_f32(c_vec, a_vec, b_vec);
+                 vst1q_f32(Ci + j, c_vec);
+             }
+             #endif
+             for (; j < n; ++j) {
+                 Ci[j] += a * bk[j];
+             }
+         }
+     }
+ }
 // OMEGA-BLOCK-END
